async ({ workspace: { read, edit }, shell: { exec } }) => {
  const g = await read("src/github.ts", { format: "hashed", offset: 12, limit: 6 });
  const ls = g.content.split("\n");
  const start = ls.find((l) => l.includes("type SupportedWebhookPayload"))!.split("|")[0];
  const end = ls.find((l) => l.includes("PullRequestReviewCommentCreatedEvent;"))!.split("|")[0];
  await edit("src/github.ts", { revision: g.revision, changes: [{ kind: "replace", start, end, content:
`type WebhookSchemas = components["schemas"];

type SupportedWebhookPayload =
	| WebhookSchemas["webhook-issue-comment-created"]
	| WebhookSchemas["webhook-issues-opened"]
	| WebhookSchemas["webhook-pull-request-opened"]
	| WebhookSchemas["webhook-pull-request-review-comment-created"];` }] });
  const i = await exec("npm uninstall @octokit/webhooks-types && npm install --save-dev @octokit/openapi-webhooks-types@^12.2.0 2>&1 | tail -3", { timeoutMs: 200000 });
